parameters.jsCode:
const release = $('Prepare Release Data').first().json;
const agentOutput = $input.first().json;
const summary = agentOutput.output
  ?? agentOutput.text
  ?? agentOutput.message?.content
  ?? agentOutput.response
  ?? `${release.name} is ready for review.`;

const APPROVAL_PROXY_URL = 'https://script.google.com/a/macros/trimble.com/s/AKfycbwsuGK26DUpFGEX9VYUGJErvwCq9iDM2K27Y7gdH1Kwn6dLnx_FDBK0ZJ7Frk4PFD5sKQ/exec';

const staticData = $getWorkflowStaticData('global');
staticData.pending = staticData.pending || {};

const approvalId = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
staticData.pending[approvalId] = {
  ...release,
  summary,
  createdAt: Date.now(),
};

const proxyBase = APPROVAL_PROXY_URL.replace(/\/$/, '');
const approveUrl = `${proxyBase}?data=${encodeURIComponent('approve:' + approvalId)}`;
const rejectUrl = `${proxyBase}?data=${encodeURIComponent('reject:' + approvalId)}`;

const linkifyReleaseBody = (body, repo) => {
  const pullBase = `https://github.com/${repo || 'trimble-oss/modus-wc-2.0'}/pull/`;
  let text = String(body || '');

  text = text.replace(/\[#(\d+)\]\((https:\/\/github\.com\/[^)]+)\)/g, '<a href="$2">#$1</a>');
  text = text.replace(/(^|[^\w[/])#(\d{2,7})(?=[\s:,\]\-]|$)/gm, (match, prefix, num) => {
    return `${prefix}<a href="${pullBase}${num}">#${num}</a>`;
  });
  text = text.replace(/^## (.+)$/gm, '<b>$1</b>');
  text = text.replace(/\n/g, '<br>');

  return text.substring(0, 3500);
};

const card = {
  cardsV2: [
    {
      cardId: `release-${release.version}`,
      card: {
        header: {
          title: release.name,
          subtitle: 'Release notes ready for review',
          imageUrl: 'https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png',
          imageType: 'CIRCLE',
        },
        sections: [
          {
            header: 'Summary',
            widgets: [{ textParagraph: { text: summary } }],
          },
          {
            header: 'Details',
            collapsible: true,
            widgets: [
              { textParagraph: { text: linkifyReleaseBody(release.body, release.repo) } },
              {
                buttonList: {
                  buttons: [
                    { text: 'Approve & Post to Group', onClick: { openLink: { url: approveUrl } } },
                    { text: 'Reject', onClick: { openLink: { url: rejectUrl } } },
                  ],
                },
              },
              {
                buttonList: {
                  buttons: [
                    { text: 'View on GitHub', onClick: { openLink: { url: release.releaseUrl } } },
                  ],
                },
              },
            ],
          },
        ],
      },
    },
  ],
};

return [{ json: { ...release, summary, approvalId, reviewCard: card } }];

