parameters.jsCode:
const APPROVAL_KEY = 'change-me-to-a-random-secret';
const input = $input.first().json;
const query = input.query || {};
const approvalId = query.id || input.id;
const key = query.key || input.key;

if (!approvalId || key !== APPROVAL_KEY) {
  throw new Error('Invalid or missing approval token. Check APPROVAL_KEY matches Apps Script and GitHub N8N_APPROVAL_KEY.');
}

const staticData = $getWorkflowStaticData('global');
const pending = staticData.pending || {};
const release = pending[approvalId];

if (!release) {
  throw new Error('Approval request not found or already processed. Send a new review card and approve within a few hours.');
}

delete pending[approvalId];

return [{ json: release }];

